    if(a==='save-choice'||a==='choose-save'){if(a==='choose-save'){s.kind=v;showDialog('save-form',el);}else showDialog('save-choice',el);return;}
    if(a==='membership-dialog'){showDialog('membership',el);return;}
    if(a==='close-dialog'){closeDialog();return;}
    if(a==='rename'||a==='share-collection'||a==='delete-collection'){s.editId=v;s.name=s.lists.find(l=>l.id===v)?.name||'';showDialog(a==='rename'?'save-form':a==='share-collection'?'sharing':'delete',el);return;}
